import React, { FormEvent } from 'react';

import ThreeDotsVertical from '@pohodnik/icons/svg/Controls/ThreeDotsVertical';
import X from '@pohodnik/icons/svg/Signs/X';

import { ObstacleIcon } from '@apps/Obstacles/components/ObstacleIcon/ObstacleIcon';
import { searchAndSelectObstacleInModalAsync } from '@apps/Obstacles/components/ObstacleSelectModal';
import { formatAltitude, formatDistance } from '@helpers/formatHelper';
import PohBadge, { BadgeVariant } from '@ui-kit/Badge/Badge';
import PohButton, { ButtonSize, ButtonVariant } from '@ui-kit/Button';
import PohCheckbox from '@ui-kit/Checkbox';
import PohDropdown from '@ui-kit/Dropdown';
import IconsEnum from '@ui-kit/Icon/IconsEnum';
import PohInput, { InputSizes, InputTypes } from '@ui-kit/Input';
import PohCol from '@ui-kit/layout/Col';
import PohRow from '@ui-kit/layout/Row';
import PohList from '@ui-kit/List';

import {
  obstacleCategoryNameResource,
  obstacleTypeNameResource,
} from '../../../../Obstacles/@resources/obstacles.resource';
import { IObstacle } from '../../../../Obstacles/@types/obstacles.types';
import {
  TEMPORARY_LINE_DASH_ARRAY,
  TEMPORARY_POINT_OPACITY,
} from '../../../@const/routeObjects.const';
import { deleteRouteObjectWithConfirm } from '../../../@helpers/delete.helper';
import { setMarkerObstacle, setMarkerStyles } from '../../../@helpers/leaflet.helper';
import { getLeafletMapManager } from '../../../@managers/leafletMap.manager';
import { getPointInfoAsync } from '../../../@services/routes.service';
import { useRoutesDispatch, useRoutesSelector } from '../../../@store/hooks';
import { setCurrentRouteObject } from '../../../@store/route.slice';
import { deleteRouteObject, updateRouteLine, updateRoutePoint } from '../../../@store/route.thunk';
import { RouteObjectType } from '../../../@types/routes.types';

const RoutesEditorObject: React.FC = () => {
  const dispatch = useRoutesDispatch();

  const { currentRouteObject } = useRoutesSelector((state) => state.route);

  const [obstacle, setObstacle] = React.useState<IObstacle | null>(null);

  const formRef = React.useRef<HTMLFormElement>(null);

  React.useEffect(() => {
    if (!formRef.current) return;
    getLeafletMapManager().setFormElement(formRef.current);
  }, []);

  React.useEffect(() => {
    if (!currentRouteObject) return;
    if (currentRouteObject.type === RouteObjectType.Line) return;
    setObstacle(currentRouteObject.obstacle);
  }, [currentRouteObject]);

  const handleDelete = async () => {
    if (!currentRouteObject) return;
    await deleteRouteObjectWithConfirm(currentRouteObject);
    await dispatch(deleteRouteObject(currentRouteObject?.id)).unwrap();
    dispatch(setCurrentRouteObject(null));
  };

  const bottomMenuActions: Record<string, () => void> = {
    Удалить: handleDelete,
    // ['Развернуть направление']: () => {

    // }
  };

  if (!currentRouteObject) return null;

  const handlerSubmit = async (e: FormEvent) => {
    e.preventDefault();
    const formData = new FormData(e.target as HTMLFormElement);
    const formDataObj: Record<string, any> = {};
    formData.forEach((value, key) => (formDataObj[key] = value));
    // console.log(formDataObj);

    getLeafletMapManager().startLoadingForCurrent();

    if (currentRouteObject.id === 0) {
      // need to save
      return;
      //dispatch(addRouteObject({ layer, cb }));
    }

    //getLeafletMapManager().completeEdit(currentRouteObject.id, false);

    if (currentRouteObject.type === RouteObjectType.Line) {
      await dispatch(
        updateRouteLine({
          line: {
            ...currentRouteObject,
            color: formDataObj.color,
            name: formDataObj.name,
            description: formDataObj.description,
            is_in_distance: formDataObj.is_in_distance === 'on',
            opacity: formDataObj.opacity,
            width: formDataObj.width,
          },
          hasCoordinatesChanges: getLeafletMapManager().hasCoordinatesChanges,
          dividePoint: formDataObj.dividePoint
            ? formDataObj.dividePoint.split(',').map(Number)
            : undefined,
          operation: formDataObj.operation ? formDataObj.operation : undefined,
        }),
      ).unwrap();
    }

    if (currentRouteObject.type === RouteObjectType.Point) {
      await dispatch(
        updateRoutePoint({
          point: {
            ...currentRouteObject,
            color: formDataObj.color,
            name: formDataObj.name,
            description: formDataObj.description,
            is_in_distance: formDataObj.is_in_distance === 'on',
            obstacle,
          },
          hasCoordinatesChanges: getLeafletMapManager().hasCoordinatesChanges,
        }),
      ).unwrap();
    }

    getLeafletMapManager().stopLoadingForCurrent();
    getLeafletMapManager().completeEdit(currentRouteObject.id);
    dispatch(setCurrentRouteObject(null));
  };

  const handleReset = (e: FormEvent) => {
    e.preventDefault();
    let layer;
    if (currentRouteObject.type === RouteObjectType.Line) {
      layer = getLeafletMapManager().getLineById(currentRouteObject.id);
      layer &&
        layer.setStyle({
          color: currentRouteObject.color,
          weight: currentRouteObject.width,
          opacity: currentRouteObject.opacity / 100,
        });
    } else if (currentRouteObject.type === RouteObjectType.Point) {
      layer = getLeafletMapManager().getPointById(currentRouteObject.id);
      setMarkerStyles(layer, {
        color: currentRouteObject.color,
        opacity: currentRouteObject.is_in_distance ? 1 : 0.5,
      });
      if (currentRouteObject.obstacle) {
        setMarkerObstacle(layer as L.Marker, currentRouteObject.obstacle);
      }
    }

    getLeafletMapManager().cancelEdit(currentRouteObject.id);
    dispatch(setCurrentRouteObject(null));
  };

  function handleHotChange(field: string, value: string | boolean | number) {
    if (!currentRouteObject) return;

    switch (field) {
      case 'temporary': {
        const isTemporary = value;

        getLeafletMapManager().updateCurrent('temporary', isTemporary);

        if (currentRouteObject.id) {
          currentRouteObject.type === RouteObjectType.Line &&
            getLeafletMapManager()
              .getLineById(currentRouteObject.id)
              ?.setStyle({ dashArray: isTemporary ? TEMPORARY_LINE_DASH_ARRAY : undefined });

          if (currentRouteObject.type === RouteObjectType.Point) {
            const point = getLeafletMapManager().getPointById(currentRouteObject.id);
            setMarkerStyles(point, { opacity: isTemporary ? TEMPORARY_POINT_OPACITY : 0 });

            if (currentRouteObject.obstacle) {
              setMarkerObstacle(point as L.Marker, currentRouteObject.obstacle);
            }
          }
        }

        break;
      }
      case 'color': {
        if (typeof value !== 'string') return;
        getLeafletMapManager().updateCurrent('color', value);
        if (currentRouteObject.id) {
          currentRouteObject.type === RouteObjectType.Line
            ? getLeafletMapManager().getLineById(currentRouteObject.id)?.setStyle({ color: value })
            : setMarkerStyles(getLeafletMapManager().getPointById(currentRouteObject.id), {
                color: value,
              });
        }
        break;
      }
      case 'opacity': {
        if (typeof value !== 'number') return;
        getLeafletMapManager().updateCurrent('opacity', value);
        currentRouteObject.id &&
          getLeafletMapManager().getLineById(currentRouteObject.id)?.setStyle({ opacity: value });
        break;
      }
      case 'width': {
        if (typeof value !== 'number') return;
        getLeafletMapManager().updateCurrent('width', value);
        currentRouteObject.id &&
          getLeafletMapManager().getLineById(currentRouteObject.id)?.setStyle({ weight: value });
        break;
      }
      default:
        throw new Error(`What is ${field}`);
    }
  }

  React.useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === 'Escape') formRef.current?.reset();
      //if (!document.activeElement && (e.key === 'Delete' || e.key === 'Backspace')) handleDelete();
    };

    document.addEventListener('keydown', handleKeyDown);
    return () => {
      document.removeEventListener('keydown', handleKeyDown);
    };
  }, []);

  return (
    <form className="m-0 p-0" onSubmit={handlerSubmit} onReset={handleReset} ref={formRef}>
      <header className="d-flex align-items-center justify-content-between px-3 py-2 bg-light">
        <strong>
          Редактирование {currentRouteObject.type === RouteObjectType.Line ? 'пути' : 'точки'}
        </strong>
        <PohButton
          size={ButtonSize.Small}
          className="flex-shrink-0"
          icon={true}
          onClick={() => formRef.current?.reset()}
        >
          <X />
        </PohButton>
      </header>
      <div className="px-3 py-2">
        <PohInput
          label="Название"
          size={InputSizes.Small}
          required
          defaultValue={currentRouteObject.name}
          labelClassName="text-muted"
          name="name"
          title="alt+click for generate name"
          onDoubleClick={async (e) => {
            if (!e.altKey) return;
            e.preventDefault();
            e.stopPropagation();
            const inp = e.target as HTMLInputElement;
            let newName = inp.value;
            if (currentRouteObject.type === RouteObjectType.Point) {
              const name1 = await getPointInfoAsync(currentRouteObject.coordinates);
              newName = name1.name || name1.display_name;
            } else {
              const name1 = await getPointInfoAsync(currentRouteObject.points[0]);
              const name2 = await getPointInfoAsync(
                currentRouteObject.points[currentRouteObject.points.length - 1],
              );

              newName = [name1.name || name1.display_name, name2.name || name2.display_name].join(
                ` – `,
              );
            }

            if (confirm(['Переименовать?', inp.value, newName].join('\n'))) {
              inp.value = newName;
            }
          }}
        />
        {currentRouteObject.type === RouteObjectType.Line && (
          <PohInput
            label="Расстояние"
            readOnly
            size={InputSizes.Small}
            defaultValue={formatDistance(currentRouteObject.distance)}
            labelClassName="text-muted"
            name="distance"
          />
        )}
        {currentRouteObject.type === RouteObjectType.Line && (
          <div className="d-none">
            <PohInput
              label="Точка разделения"
              readOnly
              size={InputSizes.Small}
              labelClassName="text-muted"
              name="dividePoint"
            />
          </div>
        )}
        {currentRouteObject.type === RouteObjectType.Line && (
          <div className="d-none">
            <PohInput
              label="Метод удаления"
              readOnly
              size={InputSizes.Small}
              labelClassName="text-muted"
              name="operation"
            />
          </div>
        )}
        <PohInput
          type={InputTypes.textarea}
          label="Описание"
          size={InputSizes.Small}
          defaultValue={currentRouteObject.description}
          labelClassName="text-muted"
          name="description"
        />
        <div className="mb-2">
          <PohCheckbox
            label="Учитывать"
            defaultChecked={currentRouteObject.is_in_distance}
            name="is_in_distance"
            onInput={(e) => {
              const isTemporary = !(e.target as HTMLInputElement).checked;
              handleHotChange('temporary', isTemporary);
            }}
          />
        </div>
        <PohRow>
          <PohCol sm={12}>
            <PohInput
              type={InputTypes.color}
              size={InputSizes.Small}
              defaultValue={currentRouteObject.color}
              title={`Цвет ${currentRouteObject.type === RouteObjectType.Line ? 'линии' : 'точки'}`}
              label="Цвет"
              name="color"
              onInput={(e) => {
                const color = (e.target as HTMLInputElement).value;
                handleHotChange('color', color);
              }}
            />
          </PohCol>
          {currentRouteObject.type === RouteObjectType.Line && (
            <>
              <PohCol>
                <PohInput
                  type={InputTypes.number}
                  min={1}
                  max={10}
                  step={1}
                  size={InputSizes.Small}
                  defaultValue={currentRouteObject.width}
                  title="Толщина линии (px)"
                  label="Толщина"
                  name="width"
                  onInput={(e) => {
                    const weight = +(e.target as HTMLInputElement).value;
                    handleHotChange('width', weight);
                  }}
                />
              </PohCol>
              <PohCol>
                <PohInput
                  type={InputTypes.number}
                  min={5}
                  max={100}
                  step={5}
                  size={InputSizes.Small}
                  defaultValue={currentRouteObject.opacity}
                  title="Прозрачность линии (%)"
                  onInput={(e) => {
                    const opacity = +(e.target as HTMLInputElement).value / 100;
                    handleHotChange('opacity', opacity);
                  }}
                  label="Прозр."
                  name="opacity"
                />
              </PohCol>
            </>
          )}
        </PohRow>
        {currentRouteObject.type === RouteObjectType.Point && (
          <>
            <p>в.н.у.м: {formatAltitude(currentRouteObject.coordinates[2]!)}</p>
            {!obstacle && (
              <PohButton
                onClick={async () => {
                  const obs = await searchAndSelectObstacleInModalAsync({
                    lat: currentRouteObject.coordinates[0],
                    lon: currentRouteObject.coordinates[1],
                    radius: 1000,
                  });
                  setObstacle(obs);
                }}
                size={ButtonSize.Small}
              >
                Привязать к POI
              </PohButton>
            )}

            {obstacle && (
              <section className="d-flex align-items-center mb-3 ">
                <div className="flex-grow-1" style={{ lineHeight: 0.9 }}>
                  <div>
                    <small className="text-muted d-flex align-items-center" style={{ gap: 4 }}>
                      <ObstacleIcon type={obstacle.type} />
                      {obstacleTypeNameResource[obstacle.type]}
                      <small className="text-muted">{formatAltitude(obstacle.altitude)}</small>
                      <PohBadge variant={BadgeVariant.Warning}>
                        {obstacleCategoryNameResource[obstacle.category]}
                      </PohBadge>
                    </small>
                    <h5 className="m-0">{obstacle.name}</h5>
                  </div>

                  <div></div>
                  {obstacle.comment && (
                    <div>
                      <em>{obstacle.comment}</em>
                    </div>
                  )}
                </div>
                <PohButton icon={IconsEnum.trash} onClick={() => setObstacle(null)} />
              </section>
            )}
          </>
        )}
      </div>
      <footer className="px-3 py-2 d-flex justify-content-between border-top">
        <PohDropdown
          className="me-n2"
          onClick={(e) => e.stopPropagation()}
          menu={Object.entries(bottomMenuActions).map(([label, callback]) => {
            return (
              <div
                key={`bottom-level-menu-item-${label}`}
                className="dropdown-item"
                onClick={callback}
              >
                {label}
              </div>
            );
          })}
        >
          <PohButton size={ButtonSize.Small} icon={true}>
            <ThreeDotsVertical />
          </PohButton>
        </PohDropdown>
        <div className="d-flex">
          <PohButton
            size={ButtonSize.Small}
            variant={ButtonVariant.Light}
            className="me-2"
            type="reset"
          >
            Отмена
          </PohButton>
          <PohButton type="submit" size={ButtonSize.Small} variant={ButtonVariant.Primary}>
            Сохранить
          </PohButton>
        </div>
      </footer>
      {currentRouteObject.type === RouteObjectType.Line && !!0 && (
        <div className="mt-auto">
          <PohList
            data={currentRouteObject.points.map((point, i) => {
              const menuActions: Record<string, () => void> = {
                ['Разделить трек на два']: () => alert('del'),
                Удалить: () => alert('del'),
              };
              return {
                key: point.join(''),
                content: (
                  <div className="row">
                    <div className="col-sm-1">{i + 1}</div>
                    <div className="col-sm-3">{point[0]}</div>
                    <div className="col-sm-3">{point[1]}</div>
                    <div className="col-sm-2">{point[2]}</div>
                    <PohDropdown
                      className="ms-auto"
                      onClick={(e) => e.stopPropagation()}
                      menu={Object.entries(menuActions).map(([label, callback]) => {
                        return (
                          <button
                            key={`bottom-level-menu-item-${label}`}
                            className="dropdown-item"
                            onClick={callback}
                            type="button"
                          >
                            {label}
                          </button>
                        );
                      })}
                    >
                      <PohButton size={ButtonSize.Small} icon={true}>
                        <ThreeDotsVertical />
                      </PohButton>
                    </PohDropdown>
                  </div>
                ),
                className: 'my-0 py-1',
                //action: true,
                onMouseOver: () => {
                  getLeafletMapManager().setHighlightedPointCoordinates(point);
                },
                onMouseLeave: () => {
                  getLeafletMapManager().clearHighlightedPoint();
                },
                onClick: (e) => {
                  getLeafletMapManager().centerOnPoint(point, e.altKey);
                },
              };
            })}
          />
        </div>
      )}
    </form>
  );
};

export default RoutesEditorObject;
