import React from 'react';

import { useMap } from 'react-leaflet';

import { watermarkToMap } from '@apps/Routes/@helpers/addToMap.helper';
import { debounce } from '@helpers/debounceHelper';
import { getArrayFromBounds } from '@helpers/leafletHelper';

import { setLeafletMapManager } from '../../../../@managers/leafletMap.manager';
import { CoordsWithOptionalEle, saveMapParamAsync } from '../../../../@services/routes.service';
import { useRoutesDispatch, useRoutesSelector } from '../../../../@store/hooks';
import {
  setActiveRouteObject,
  setActiveRouteObjectById,
  setCurrentRouteObject,
  setCurrentRouteObjectById,
  setNewRouteObject,
  updateCurrentRouteObjectPoints,
  updateNewRouteObjectPoints,
} from '../../../../@store/route.slice';
import { addRouteObject } from '../../../../@store/route.thunk';
import {
  IBaseRouteObjectLine,
  IRouteObject,
  RouteObjectType,
} from '../../../../@types/routes.types';

interface IInitForMapProps {}

const InitForMap: React.FC<IInitForMapProps> = () => {
  const { routeInfo, mapTypes } = useRoutesSelector((state) => state.route);
  const dispatch = useRoutesDispatch();

  const map = useMap();

  React.useEffect(() => {
    const handleMoveEnd = () => {
      if (!routeInfo) return;
      if (!map) return;
      const bds = map.getBounds();
      const arr = getArrayFromBounds(bds);
      debounce(() => saveMapParamAsync(routeInfo?.id, 'bounds', JSON.stringify(arr)), 1000);
    };

    const handleBaseLayerChange = (e: { name: string }) => {
      if (!routeInfo) return;
      const idType = mapTypes.find((x) => x.name === e.name)?.id;
      idType && saveMapParamAsync(routeInfo.id, 'id_type', idType);
    };

    if (routeInfo && routeInfo.bounds) {
      map.fitBounds(routeInfo.bounds);
    }

    watermarkToMap(map);

    setLeafletMapManager(
      map,
      function onAddCallback(layer, cb, name) {
        dispatch(addRouteObject({ layer, cb, name }))
          .unwrap()
          .then((newRo) => {
            dispatch(setCurrentRouteObjectById(newRo.id));
          });
        dispatch(setNewRouteObject(null));
      },
      function onEditStarted(id, layer) {
        if (!routeInfo) return;
        console.info('setLeafletMapManager onEditStarted', { id, layer, id_route: routeInfo.id });
        dispatch(setCurrentRouteObjectById(id));
      },
      function onSelectRouteObject(id) {
        console.info('setLeafletMapManager onActivate', { id });
        id ? dispatch(setActiveRouteObjectById(id)) : dispatch(setActiveRouteObject(null));
      },
      function onHotChange(
        coordinates: CoordsWithOptionalEle[],
        activeLayerId: IRouteObject['id'] | null,
      ) {
        activeLayerId
          ? dispatch(updateCurrentRouteObjectPoints(coordinates))
          : dispatch(updateNewRouteObjectPoints(coordinates));
      },
      function addStartCallback() {
        const emptyLine: IBaseRouteObjectLine = {
          id: 0,
          name: '',
          description: '',
          dateCreate: new Date().toISOString(),
          dateUpdate: new Date().toISOString(),
          updater: null,
          is_in_distance: true,
          type: RouteObjectType.Line,
          points: [],
          distance: 0,
          color: '#ff0000',
          width: 1,
          opacity: 100,
          order: 0,
        };

        dispatch(setActiveRouteObject(null));
        dispatch(setCurrentRouteObject(null));
        dispatch(setNewRouteObject(emptyLine));
      },
    );

    map.on('moveend', handleMoveEnd);
    map.on('baselayerchange', handleBaseLayerChange);

    return () => {
      map.off('moveend', handleMoveEnd);
      map.off('baselayerchange', handleBaseLayerChange);
    };
  }, [map, routeInfo]);

  return null;
};

export default InitForMap;
