import * as L from 'leaflet';

import styles from './styles.module.less';
import { getDivIcon, setMarkerStyles } from '../../@helpers/leaflet.helper';

export enum XneekPointEditorState {
  Idle,
  Started,
  Drawing,
  Editing,
}

export interface IXneekPointEditorOptions {
  color: string;
  opacity: number;
}

const defaultOptions = {
  color: 'red',
  opacity: 1,
};

const mapClassName = 'xneek-map-e-point';

export class XneekPointEditor {
  private readonly map: L.Map;
  private options: IXneekPointEditorOptions = defaultOptions;

  private marker: L.Marker | null = null;

  private isDrawing = false;

  private onChangeHandler:
    | ((latlng: L.LatLng, updatePoint?: (latlng: L.LatLng) => void) => void)
    | undefined;
  private onSaveHandler: ((latlng: L.LatLng | null) => void) | undefined;
  private onStateChangeHandler: ((state: XneekPointEditorState) => void) | undefined;
  private onPointContextmenuHandler:
    | ((
        e: L.LeafletEvent,
        callbacks: {
          remove: () => void;
          setLatLng: (latLng: L.LatLng) => void;
        },
      ) => void)
    | undefined;

  state: XneekPointEditorState = XneekPointEditorState.Idle;

  constructor(map: L.Map, options: Partial<IXneekPointEditorOptions> = {}) {
    this.map = map;
    this.options = {
      ...this.options,
      ...options,
    };
  }

  private init() {
    this.map.on('click', this.handleMapClick);

    L.DomUtil.addClass(this.getMapContainerNode(), mapClassName);
  }

  destroy() {
    this.map.off('click', this.handleMapClick);

    this.marker && this.map.removeLayer(this.marker);
    this.marker && this.marker.remove();
    this.onChangeHandler = undefined;
    this.onSaveHandler = undefined;
    this.onStateChangeHandler = undefined;

    this.isDrawing = false;

    L.DomUtil.removeClass(this.getMapContainerNode(), mapClassName);
  }

  private getMapContainerNode = (): HTMLElement => {
    // eslint-disable-next-line @typescript-eslint/ban-ts-comment
    // @ts-ignore
    return this.map._container;
  };

  private setState(state: XneekPointEditorState) {
    this.state = state;

    const container = this.getMapContainerNode();
    if (
      this.state === XneekPointEditorState.Started ||
      this.state === XneekPointEditorState.Drawing
    ) {
      L.DomUtil.addClass(container, styles.mapEditable);
    } else {
      L.DomUtil.removeClass(container, styles.mapEditable);
    }

    if (this.onStateChangeHandler) {
      this.onStateChangeHandler(state);
    }
  }

  private addMarker(latlng: L.LatLng) {
    const marker = L.marker(latlng, { draggable: true, icon: getDivIcon() });

    marker.on('click', (e: L.LeafletEvent) => {
      L.DomEvent.stopPropagation(e);
    });

    marker.on('dragstart', (e: L.LeafletEvent) => {
      L.DomEvent.stopPropagation(e);

      const handleDrag = (ev: L.LeafletEvent) => {
        L.DomEvent.stopPropagation(ev);
        if (this.onChangeHandler) {
          this.onChangeHandler(marker.getLatLng(), (_latlng) => marker.setLatLng(latlng));
        }
      };

      marker.on('drag', handleDrag);

      marker.on('dragstop', (_e: L.LeafletEvent) => {
        L.DomEvent.stopPropagation(e);
        marker.off('drag', handleDrag);
      });
    });

    marker.on('contextmenu', (e: L.LeafletEvent) => {
      if (this.onPointContextmenuHandler) {
        L.DomEvent.stopPropagation(e);
        this.onPointContextmenuHandler(e, {
          remove: () => {
            this.onSaveHandler && this.onSaveHandler(null);
            this.destroy();
          },
          setLatLng: (latlngE: L.LatLng) => {
            marker.setLatLng(latlngE);
            this.onSaveHandler && this.onSaveHandler(latlngE);
          },
        });
      }
    });

    marker.addTo(this.map);

    setMarkerStyles(marker, this.options);

    this.marker = marker;

    if (this.onChangeHandler) {
      this.onChangeHandler(this.marker.getLatLng(), (latlngE) => this.marker?.setLatLng(latlngE));
    }

    return marker;
  }

  handleMapClick = (e: L.LeafletMouseEvent) => {
    const targetEl = e.originalEvent.srcElement;
    if (targetEl && !(targetEl as HTMLElement).classList.contains(mapClassName)) {
      return; // Все что не непсредствено на карту отбрасываем
    }

    if (!this.isDrawing) {
      if (this.onSaveHandler && this.marker) {
        this.onSaveHandler(this.marker.getLatLng());
      }
      this.stopEdit();
      return;
    }

    this.addMarker(e.latlng);
    this.setState(XneekPointEditorState.Editing);
    this.isDrawing = false;
  };

  onChange(cb: typeof this.onChangeHandler) {
    this.onChangeHandler = cb;
  }

  onSave(cb: typeof this.onSaveHandler) {
    this.onSaveHandler = cb;
  }

  onStateChange(cb: typeof this.onStateChangeHandler) {
    this.onStateChangeHandler = cb;
  }
  onPointContextmenu(cb: typeof this.onPointContextmenuHandler) {
    this.onPointContextmenuHandler = cb;
  }
  startEdit(
    latlng: L.LatLng | null = null,
    options: Partial<IXneekPointEditorOptions> = defaultOptions,
  ) {
    this.setPointOptions({ ...defaultOptions, ...options });
    if (this.isDrawing) {
      if (this.onSaveHandler && this.marker) {
        this.onSaveHandler(this.marker.getLatLng());
      }
    }
    this.destroy();

    this.isDrawing = true;
    this.setState(XneekPointEditorState.Started);
    this.init();

    if (latlng) {
      this.addMarker(latlng);
      this.isDrawing = false;
      this.setState(XneekPointEditorState.Editing);
    }
  }

  stopEdit() {
    this.isDrawing = false;
    this.setState(XneekPointEditorState.Idle);
    this.destroy();
  }

  setPointOptions(options: Partial<IXneekPointEditorOptions>) {
    this.options = { ...this.options, ...options };
    setMarkerStyles(this.marker, this.options);
  }
}

let instance: XneekPointEditor | null = null;

export const getXneekPointEditorSingletone = (
  map: L.Map,
  options: Partial<IXneekPointEditorOptions> = {},
) => {
  if (instance) return instance;
  instance = new XneekPointEditor(map, options);
  return instance;
};
