import { parseStringAsGPX } from '../../../@helpers/gpxParse.heplper';
import { IGpx } from '../../../@types/gpx.types';

export const processGPXFile = (file: File): Promise<IGpx> => {
  return new Promise((resolve) => {
    const fileReader = new FileReader();

    fileReader.onload = (loadEvent) => {
      if (!loadEvent?.target) return;
      if (loadEvent.target.readyState != 2) return;
      if (loadEvent.target.error)
        throw new Error('Error while reading file ' + file.name + ': ' + loadEvent.target.error);
      if (!loadEvent.target.result)
        throw new Error(
          'loadEvent.target.result invalid' + file.name + ': ' + loadEvent.target.error,
        );

      const data = parseStringAsGPX(loadEvent.target.result as string);

      resolve(data);
    };
    fileReader.readAsText(file);
  });
};
