import React from 'react';

import { showModal } from '@ui-kit/Modal';

import PointsAroundModal from './PointsAroundModal';
import { IPointAround } from '../../../@services/routes.service';

export interface IPointWithName {
  point: [number, number];
  name?: string;
}

export const getPointAround = async (
  lat: number,
  lon: number,
  radius = 500,
): Promise<IPointAround> => {
  return new Promise((resolve) => {
    showModal({
      title: 'Точки вокруг',
      children: (clos: () => void) => (
        <PointsAroundModal
          lat={lat}
          lon={lon}
          radius={radius}
          onChange={(res) => {
            resolve(res);
            clos();
          }}
        />
      ),
    });
  });
};
