import { handleApiError } from '@helpers/httpClient';

export interface IGraphhopperResponsePath {
  distance: number;
  ascend: number;
  descend: number;
  weight: number;
  time: number;
  transfers: number;
  points_encoded: boolean;
  bbox: [number, number, number, number];
  points: {
    type: 'LineString';
    coordinates: [number, number, number][];
  };
}
export interface IGraphhopperResponse {
  hints: {
    'visited_nodes.sum': number;
    'visited_nodes.average': number;
  };
  paths: IGraphhopperResponsePath[];
  info: {
    copyrights: ['GraphHopper', 'OpenStreetMap contributors'];
    took: 5;
    road_data_timestamp: '2025-07-14T13:00:00Z';
  };
}

const keys = [
  'e04aaf51-2340-4ee2-8514-11d4cb045bba',
  '4bd04482-b045-436c-9dba-97ea54d30e12',
  '3cfc5fc6-3dba-4e7d-a634-204400d70c29',
];

const fuckingJson = (url: string) => {
  return new Promise((res, rej) => {
    // eslint-disable-next-line @typescript-eslint/ban-ts-comment
    //@ts-ignore
    $.getJSON(url, res, rej);
  });
};

export const getRoutesVariants = async (
  points: [number, number][],
  { optimize = true, vehicle = 'foot' }: { optimize: boolean; vehicle: string },
): Promise<IGraphhopperResponse> => {
  const params = {
    key: keys[Math.round(Math.random() * 2)],
    optimize: optimize.toString(),
    locale: 'ru',
    instructions: 'false',
    vehicle,
    elevation: 'true',
    points_encoded: 'false',
    calc_points: 'true',
  };
  const search = new URLSearchParams(params);
  const pointsStr = points.map(([lat, lon]) => `${lat},${lon}`).join('&point=');

  const url = `https://graphhopper.com/api/1/route?${search}&point=${pointsStr}`;
  const res = await fuckingJson(url).then(handleApiError);
  return res;
};

