import React from 'react';

import Bezier2 from '@pohodnik/icons/svg/Graphics/Bezier2';

import PohButton, { ButtonVariant } from '@ui-kit/Button';
import PohList from '@ui-kit/List';

import { IBaseRouteObjectLine } from '../../../@types/routes.types';
import RoutesEditorListItem from '../RoutesEditorSidebar/RoutesEditorListItem';

export interface IJoinTracksModalProps {
  currentLine: IBaseRouteObjectLine;
  anotherLines: IBaseRouteObjectLine[];
  onConfirm: (lineForJoin: IBaseRouteObjectLine) => void;
}

const JoinTracksModal: React.FC<IJoinTracksModalProps> = ({
  currentLine,
  anotherLines,
  onConfirm,
}) => {
  const [activeLine, setActiveLine] = React.useState<IBaseRouteObjectLine | null>(null);

  const handleSubmit = async () => {
    activeLine && onConfirm(activeLine);
  };

  return (
    <section>
      <p>
        Выберите трек, точки которого будут добавлены к треку
        <span
          style={{
            color: currentLine.color,
            fontSize: 18,
            opacity: currentLine.is_in_distance ? 1 : 0.5,
          }}
        >
          <Bezier2 />
        </span>
        &quot;{currentLine.name}&quot;
      </p>
      <PohList
        data={anotherLines
          .toSorted((a, b) => a.order - b.order)
          .map((line) => {
            return {
              key: line.id,
              className: 'p-0',
              children: <RoutesEditorListItem routeObject={line} />,
              active: line.id === activeLine?.id,
              onClick: () => {
                setActiveLine(line);
              },
            };
          })}
      />

      <footer className="p-3 text-end">
        <PohButton variant={ButtonVariant.Primary} disabled={!activeLine} onClick={handleSubmit}>
          Объединить
        </PohButton>
      </footer>
    </section>
  );
};

export default JoinTracksModal;
