import React from 'react';

import * as L from 'leaflet';

import { getDefaultTileLayer, getMap } from '@helpers/leafletHelper';
import PohButton, { ButtonVariant } from '@ui-kit/Button';

import { ILayerWithName } from '.';
import { processGPXFile } from './importGpx.helper';
import { getDivIcon } from '../../../@helpers/leaflet.helper';

interface IImportGPXModalProps {
  onChange: (layers: ILayerWithName[]) => void;
}

interface IResultWithChecked extends ILayerWithName {
  checked?: boolean;
}

const ImportGPXModal: React.FC<IImportGPXModalProps> = ({ onChange }) => {
  const [results, setResults] = React.useState<IResultWithChecked[]>([]);

  const ref = React.useRef<HTMLDivElement>(null);
  const mapRef = React.useRef<L.Map>(null);
  const layerGroupRef = React.useRef<L.FeatureGroup>(null);

  React.useEffect(() => {
    if (!ref.current) return;
    if (!mapRef.current) {
      mapRef.current = getMap(ref.current as HTMLElement);
      getDefaultTileLayer().addTo(mapRef.current);
      layerGroupRef.current = L.featureGroup().addTo(mapRef.current);
    }

    layerGroupRef.current && layerGroupRef.current.clearLayers();

    results.forEach((r) => {
      if (!layerGroupRef.current) return;
      r.layer.bindTooltip(r.name ?? '');
      r.layer.on('click', () => {
        setResults((cur) => cur.filter((rr) => rr.layer !== r.layer));
        layerGroupRef.current?.removeLayer(r.layer);
      });
      r.layer.addTo(layerGroupRef.current);
    });

    const bounds = layerGroupRef.current?.getBounds();
    if (bounds && bounds.isValid()) mapRef.current.fitBounds(bounds);
  }, [results]);

  return (
    <section style={{ width: 800 }}>
      <div ref={ref} style={{ height: 360 }}></div>
      <input
        type="file"
        multiple
        accept=".gpx"
        onChange={async (e) => {
          if (!e.target.files) return;

          for (const file of e.target.files) {
            const res = await processGPXFile(file);
            setResults((cur) => {
              const newResults: IResultWithChecked[] = [];

              res.wpt.forEach((wpt) => {
                newResults.push({
                  name: wpt.name,
                  checked: true,
                  layer: new L.Marker([wpt.lat, wpt.lon, wpt.ele], { icon: getDivIcon() }),
                });
              });

              res.trk.forEach((trk) => {
                trk.trkseg.forEach((segment, segment_index) => {
                  newResults.push({
                    name: [trk.name, segment_index].filter(Boolean).join('_'),
                    checked: true,
                    layer: new L.Polyline(segment.trkpt.map((p) => [p.lat, p.lon, p.ele])),
                  });
                });
              });

              res.rte.forEach((rte) => {
                newResults.push({
                  name: rte.name,
                  checked: true,
                  layer: new L.Polyline(rte.rtept.map((p) => [p.lat, p.lon, p.ele])),
                });
              });

              return [...cur, ...newResults];
            });
          }
        }}
      />
      <footer className="p-3 text-end">
        <PohButton
          variant={ButtonVariant.Primary}
          disabled={!results.length}
          onClick={() => onChange(results)}
        >
          Import
        </PohButton>
      </footer>
    </section>
  );
};

export default ImportGPXModal;
