import React, { FormEvent } from 'react';

import X from '@pohodnik/icons/svg/Signs/X';

import PohButton, { ButtonSize, ButtonVariant } from '@ui-kit/Button';
import PohInput, { InputSizes, InputTypes } from '@ui-kit/Input';

import { AllowMapParamsForSave, saveMapParamAsync } from '../../../@services/routes.service';
import { useRoutesDispatch, useRoutesSelector } from '../../../@store/hooks';
import { setIsBaseParamsEditorOpen, updateRouteInfo } from '../../../@store/route.slice';
import { IBaseRoute } from '../../../@types/routes.types';

const RoutesEditorBaseParams: React.FC = () => {
  const dispatch = useRoutesDispatch();

  const [isLoading, setIsLoading] = React.useState(false);

  const { isBaseParamsEditorOpen, routeInfo } = useRoutesSelector((state) => state.route);

  const formRef = React.useRef<HTMLFormElement>(null);

  if (!isBaseParamsEditorOpen || !routeInfo) return null;

  const handlerSubmit = async (e: FormEvent) => {
    e.preventDefault();
    setIsLoading(true);
    const formData = new FormData(e.target as HTMLFormElement);
    const formDataObj: Record<string, any> = {};
    formData.forEach((value, key) => (formDataObj[key] = value));
    const tasks: Promise<any>[] = [];

    Object.entries(formDataObj).map(([key, value]) => {
      if (routeInfo[key as keyof IBaseRoute] !== value) {
        tasks.push(
          saveMapParamAsync(
            routeInfo.id,
            key === 'description' ? 'desc' : (key as AllowMapParamsForSave),
            value,
          ),
        );
      }
    });
    await Promise.all(tasks);
    setIsLoading(false);
    dispatch(updateRouteInfo({ ...routeInfo, ...formDataObj }));
    dispatch(setIsBaseParamsEditorOpen(false));
  };

  const handleCancel = () => {
    dispatch(setIsBaseParamsEditorOpen(false));
  };

  return (
    <form className="m-0 p-0" onSubmit={handlerSubmit} ref={formRef}>
      <header className="d-flex align-items-center justify-content-between px-3 py-2 bg-light">
        <strong>Редактирование</strong>
        <PohButton
          size={ButtonSize.Small}
          className="flex-shrink-0"
          icon={true}
          onClick={handleCancel}
        >
          <X />
        </PohButton>
      </header>
      <div className="px-3 py-2">
        <PohInput
          label="Название"
          size={InputSizes.Small}
          required
          disabled={isLoading}
          defaultValue={routeInfo.name}
          labelClassName="text-muted"
          name="name"
        />

        <PohInput
          type={InputTypes.textarea}
          label="Описание"
          size={InputSizes.Small}
          defaultValue={routeInfo.description}
          labelClassName="text-muted"
          name="description"
          disabled={isLoading}
        />
      </div>
      <footer className="px-3 py-2 d-flex justify-content-end border-top">
        <div className="d-flex">
          <PohButton
            disabled={isLoading}
            size={ButtonSize.Small}
            variant={ButtonVariant.Light}
            className="me-2"
            onClick={handleCancel}
          >
            Отмена
          </PohButton>
          <PohButton
            disabled={isLoading}
            type="submit"
            size={ButtonSize.Small}
            variant={ButtonVariant.Primary}
          >
            Сохранить
          </PohButton>
        </div>
      </footer>
    </form>
  );
};

export default RoutesEditorBaseParams;
