import * as L from 'leaflet';

import styles from './styles.module.less';

export class XneekLoader {
  constructor() {}
  startLoadingForPolyline(polyline: L.Polyline) {
    polyline.getElement()?.classList?.add?.(styles.polylineLoading);
  }
  stopLoadingForPolyline(polyline: L.Polyline) {
    polyline.getElement()?.classList?.remove?.(styles.polylineLoading);
  }

  startLoadingForMarker(marker: L.Marker) {
    marker.getElement()?.classList?.add?.(styles.markerLoading);
  }
  stopLoadingForMarker(marker: L.Marker) {
    marker.getElement()?.classList?.remove?.(styles.markerLoading);
  }
}
