import React from 'react';

import ThreeDotsVertical from '@pohodnik/icons/svg/Controls/ThreeDotsVertical';
import * as L from 'leaflet';
import { useNavigate } from 'react-router-dom';

import { searchAndSelectObstacleInModalAsync } from '@apps/Obstacles/components/ObstacleSelectModal';
import { success } from '@helpers/notificationHelper';
import PohAva from '@ui-kit/Ava';
import PohButton, { ButtonSize } from '@ui-kit/Button';
import PohDropdown from '@ui-kit/Dropdown';
import PohLoader, { LoaderVariant } from '@ui-kit/Loader';
import { confirmModal2 } from '@ui-kit/Modal/modalsHelper';

import MapPreviewUpdater from './MapPreviewUpdater';
import { downloadGpx, IGetGPXStringTracks } from '../../../@helpers/gpx.helper';
import { copyRouteAsync, deleteRouteAsync } from '../../../@services/routes.service';
import { useRoutesDispatch, useRoutesSelector } from '../../../@store/hooks';
import {
  setIsAccessParamsEditorOpen,
  setIsBaseParamsEditorOpen,
  setIsSearchOpen,
  updateRouteInfo,
} from '../../../@store/route.slice';
import { addRouteObject } from '../../../@store/route.thunk';
import { IBaseRouteObjectLine, RouteObjectType } from '../../../@types/routes.types';
import { clearRoute } from '../ClearRoute';
import { importGpxModal } from '../ImportGPX';

const RoutesEditorSidebarHeader: React.FC = () => {
  const [isPreviewUpdate, setIsPreviewUpdate] = React.useState(false);
  const { routeInfo, routeObjects } = useRoutesSelector((state) => state.route);
  const dispatch = useRoutesDispatch();
  const navigate = useNavigate();
  const downloadFullGpx = (asRoute = false, join = false, onlyInDistance = false) => {
    const ro = routeObjects.toSorted((a, b) => a.order - b.order);
    let lines: IGetGPXStringTracks[] = ro
      .filter((r) => r.type === RouteObjectType.Line && (!onlyInDistance || r.is_in_distance))
      .map((r) => ({
        name: r.name,
        description: r.description,
        coordinates: (r as IBaseRouteObjectLine).points,
      }));
    if (join) {
      lines = [
        lines.reduce<IGetGPXStringTracks>(
          (acc, val) => {
            acc.description += val.name + ';\n';
            acc.coordinates.push(...val.coordinates);
            return acc;
          },
          { name: 'joined', description: '', coordinates: [] },
        ),
      ];
    }

    downloadGpx(
      lines,
      ro
        .filter((r) => r.type === RouteObjectType.Point)
        .map((r) => ({ name: r.name, description: r.description, coordinate: r.coordinates })),
      {
        asRoute,
        name: routeInfo?.name,
        description: routeInfo?.description,
        author: routeInfo?.author?.name,
        date: new Date(routeInfo?.dateCreate ?? new Date()),
      },
    );
  };

  const menuActions: Record<string, (e: MouseEvent) => void> = {
    'Поиск объектов': () => dispatch(setIsSearchOpen(true)),
    'Основные параметры маршрута': () => dispatch(setIsBaseParamsEditorOpen(true)),
    'Права доступа': () => dispatch(setIsAccessParamsEditorOpen(true)),
    'Обновить превью/картинку': () => setIsPreviewUpdate(true),
    '---': () => 0,
    'Импорт из GPX': () => {
      importGpxModal().then((results) => {
        for (const res of results) {
          dispatch(addRouteObject({ layer: res.layer, name: res.name, cb: () => {} })).unwrap();
        }
      });
    },
    'Экспорт в GPX (трек)': (e) => downloadFullGpx(false, e.ctrlKey || e.shiftKey, e.altKey),
    'Экспорт в GPX (маршрут)': (e) => downloadFullGpx(true, e.ctrlKey || e.shiftKey, e.altKey),
    'Добавить POI': () => {
      searchAndSelectObstacleInModalAsync().then((result) => {
        dispatch(
          addRouteObject({
            layer: new L.Marker([...result.coordinates, result.altitude]),
            name: result.name,
            id_obstacle: result.id,
            cb: () => {},
          }),
        ).unwrap();
      });
    },
    '----': () => 0,
    'Создать копию маршрута': async () => {
      const ok = await confirmModal2(
        'Маршрут будет Скопирован вместе со всеми объектами! Хотите продолжить?',
      );
      if (ok && routeInfo) {
        const newRouteId = await copyRouteAsync(routeInfo.id);
        success('Маршрут скопирован!');
        navigate(`/routes/${newRouteId}/edit`);
      }
    },
    '-----': () => 0,
    'Очистить маршрут': async () => {
      if (!routeInfo?.id) return;
      await clearRoute(routeInfo.id);

      success('Маршрут очищен!');
      window.location.reload();
    },
    'Удалить маршрут': async () => {
      const ok = await confirmModal2('Маршрут будет удалён! Хотите продолжить?');
      if (ok && routeInfo) {
        await deleteRouteAsync(routeInfo.id);
        success('Маршрут удалён!');
        window.history.back();
      }
    },
  };

  return (
    <header className="py-1 bg-light border-bottom d-flex align-items-center w-100">
      <div className="flex-shrink-0 ms-2 position-relative" style={{ height: 48, width: 48 }}>
        {isPreviewUpdate && (
          <div className="position-absolute d-flex align-items-center justify-content-center w-100 h-100">
            <PohLoader variant={LoaderVariant.Dark} />
          </div>
        )}
        <PohAva
          onClick={() => setIsPreviewUpdate(true)}
          src={routeInfo?.previewImg}
          style={{ height: 48, width: 48 }}
          alt={routeInfo?.name}
        />
      </div>

      {isPreviewUpdate && (
        <MapPreviewUpdater
          onComplete={(res) => {
            setIsPreviewUpdate(false);
            routeInfo && dispatch(updateRouteInfo({ ...routeInfo, previewImg: res }));
          }}
        />
      )}
      <div
        onDoubleClick={() => dispatch(setIsBaseParamsEditorOpen(true))}
        className="flex-grow-1 mx-2"
        style={{ minWidth: 0 }}
      >
        <strong className="m-0 text-truncate d-block" title={routeInfo?.name}>
          {routeInfo?.name}
        </strong>
        <small className="text-muted d-block  text-truncate" title={routeInfo?.description}>
          {routeInfo?.description}
        </small>
      </div>
      <aside className="flex-shrink-0">
        <PohDropdown
          onClick={(e) => e.stopPropagation()}
          menu={Object.entries(menuActions).map(([label, callback]) => {
            if (label.startsWith('---'))
              return (
                <li key={`bottom-level-menu-item-${label}`}>
                  <hr className="dropdown-divider" />
                </li>
              );

            return (
              <div
                key={`bottom-level-menu-item-${label}`}
                className="dropdown-item"
                onClick={(e) => callback(e as any)}
              >
                {label}
              </div>
            );
          })}
        >
          <PohButton size={ButtonSize.Small} icon={true}>
            <ThreeDotsVertical />
          </PohButton>
        </PohDropdown>
      </aside>
    </header>
  );
};

export default RoutesEditorSidebarHeader;
