import React from 'react';

import clsx from 'clsx';

import RoutesEditorAccess from './RoutesEditorAccess';
import RoutesEditorBaseParams from './RoutesEditorBaseParams';
import RoutesEditorList from './RoutesEditorList';
import RoutesEditorObject from './RoutesEditorObject';
import RoutesEditorSearch from './RoutesEditorSearch';
import RoutesEditorSidebarFooter from './RoutesEditorSidebarFooter';
import RoutesEditorSidebarHeader from './RoutesEditorSidebarHeader';
import { useRoutesSelector } from '../../../@store/hooks';
const RoutesEditorSidebar: React.FC = () => {
  const {
    currentRouteObject,
    isBaseParamsEditorOpen,
    isAccessParamsEditorOpen,
    isSidebarCollapsed,
    isSearchOpen,
  } = useRoutesSelector((state) => state.route);

  return (
    <aside
      className={clsx(' shadow flex-column h-100 ', isSidebarCollapsed ? 'd-none' : 'd-flex')}
      style={{ width: 340, overflowY: 'auto' }}
    >
      {currentRouteObject?.id && <RoutesEditorObject key={currentRouteObject?.id} />}
      {isBaseParamsEditorOpen && <RoutesEditorBaseParams />}
      {isAccessParamsEditorOpen && <RoutesEditorAccess />}
      {isSearchOpen && <RoutesEditorSearch />}

      {!currentRouteObject?.id &&
        !isBaseParamsEditorOpen &&
        !isSearchOpen &&
        !isAccessParamsEditorOpen && (
          <div
            style={{ flexGrow: 1, height: 1 }}
            className={clsx(
              'd-flex flex-column',
              (currentRouteObject?.id || isBaseParamsEditorOpen) && 'd-none',
            )}
          >
            <RoutesEditorSidebarHeader />
            <RoutesEditorList className="flex-grow-1" />
            <RoutesEditorSidebarFooter />
          </div>
        )}
    </aside>
  );
};

export default RoutesEditorSidebar;
