import { createSlice } from '@reduxjs/toolkit';
import type { PayloadAction } from '@reduxjs/toolkit';
import * as L from 'leaflet';

import { routeThunks } from './route.thunk';
import { IBaseRoute, IBaseRouteObjectLine, IMapType, IRouteObject } from '../@types/routes.types';

export interface RouteState {
  isBaseInfoLoading: boolean;
  baseInfoError?: Error;

  routeInfo: IBaseRoute | null;
  mapTypes: IMapType[];
  currentMapType: IMapType | null;

  isRouteObjectsLoading: boolean;
  routeObjectsError?: Error;
  routeObjects: IRouteObject[];

  currentRouteObject: IRouteObject | null;
  activeRouteObject: IRouteObject | null;
  newRouteObject: IRouteObject | null;

  pointsLayers: Record<IRouteObject['id'], L.Marker>;
  linesLayers: Record<IRouteObject['id'], L.Polyline>;

  filters: {
    showLines: boolean;
    showPoints: boolean;
    showNotInDistance: boolean;
  };

  isSidebarCollapsed: boolean;
  isBaseParamsEditorOpen: boolean;
  isAccessParamsEditorOpen: boolean;
  isSearchOpen: boolean;
}

const initialState: RouteState = {
  isBaseInfoLoading: false,
  routeInfo: null,
  mapTypes: [],
  currentMapType: null,

  isRouteObjectsLoading: false,
  routeObjects: [],

  currentRouteObject: null,
  activeRouteObject: null,
  newRouteObject: null,

  pointsLayers: {},
  linesLayers: {},

  filters: {
    showLines: true,
    showPoints: true,
    showNotInDistance: true,
  },

  isSidebarCollapsed: false,
  isBaseParamsEditorOpen: false,
  isAccessParamsEditorOpen: false,
  isSearchOpen: false,
};

export const routeSlice = createSlice({
  name: 'route',
  initialState,
  reducers: {
    setCurrentRouteObject: (state, action: PayloadAction<IRouteObject | null>) => {
      state.currentRouteObject = action.payload;
    },
    updateCurrentRouteObjectPoints: (
      state,
      action: PayloadAction<Array<[number, number] | [number, number, number]>>,
    ) => {
      if (!state.currentRouteObject) {
        console.warn('updateCurrentRouteObjectPoints skipped');
        return;
      }
      (state.currentRouteObject as IBaseRouteObjectLine).points = action.payload;
    },
    updateNewRouteObjectPoints: (
      state,
      action: PayloadAction<Array<[number, number] | [number, number, number]>>,
    ) => {
      (state.newRouteObject as IBaseRouteObjectLine).points = action.payload;
    },
    setNewRouteObject: (state, action: PayloadAction<IRouteObject | null>) => {
      state.newRouteObject = action.payload;
    },
    setCurrentRouteObjectById: (state, action: PayloadAction<IRouteObject['id']>) => {
      state.currentRouteObject = state.routeObjects.find((ro) => ro.id === action.payload) ?? null;
    },
    setActiveRouteObjectById: (state, action: PayloadAction<IRouteObject['id'] | null>) => {
      state.activeRouteObject = state.routeObjects.find((ro) => ro.id === action.payload) ?? null;
    },
    setActiveRouteObject: (state, action: PayloadAction<IRouteObject | null>) => {
      state.activeRouteObject = action.payload ?? null;
    },
    setRouteObjects: (state, action: PayloadAction<IRouteObject[]>) => {
      state.routeObjects = action.payload;
    },

    addNewRouteObject: (state, action: PayloadAction<IRouteObject>) => {
      state.routeObjects = [
        ...state.routeObjects,
        { ...action.payload, order: (state.routeObjects.at(-1)?.order ?? 0) + 1 },
      ];
    },

    setFilters: (state, action: PayloadAction<RouteState['filters']>) => {
      state.filters = action.payload;
    },

    setIsBaseParamsEditorOpen(state, action: PayloadAction<RouteState['isBaseParamsEditorOpen']>) {
      state.isBaseParamsEditorOpen = action.payload;
    },
    setIsAccessParamsEditorOpen(
      state,
      action: PayloadAction<RouteState['isAccessParamsEditorOpen']>,
    ) {
      state.isAccessParamsEditorOpen = action.payload;
    },
    setIsSearchOpen(state, action: PayloadAction<RouteState['isSearchOpen']>) {
      state.isSearchOpen = action.payload;
    },
    updateRouteInfo(state, action: PayloadAction<IBaseRoute>) {
      state.routeInfo = {
        ...state.routeInfo,
        ...action.payload,
      };
    },
    toggleSidebar(state) {
      state.isSidebarCollapsed = !state.isSidebarCollapsed;
    },
  },
  extraReducers: routeThunks,
});

export const {
  setCurrentRouteObject,
  setCurrentRouteObjectById,
  setActiveRouteObjectById,
  updateCurrentRouteObjectPoints,
  updateNewRouteObjectPoints,
  setNewRouteObject,
  setActiveRouteObject,
  setRouteObjects,
  addNewRouteObject,
  setFilters,
  setIsBaseParamsEditorOpen,
  setIsAccessParamsEditorOpen,
  setIsSearchOpen,
  updateRouteInfo,
  toggleSidebar,
} = routeSlice.actions;

export const selectCurrentRouteObject = (state: RouteState) => state.currentRouteObject;

export default routeSlice.reducer;
