import React from 'react';

import notificationHelper from '@helpers/notificationHelper';
import { showModal } from '@ui-kit/Modal/modalsHelper';

import RouteAuto, { IRouteAutoProps } from '.';

export const getAutoRouteFromPoints = (args: IRouteAutoProps) => {
  if (args.points.length > 5) {
    notificationHelper.warn('не умеем больше 5 точек');
    return;
  }
  return showModal({
    title: 'Автоматический построитель маршрута',
    children: (clos: any) => (
      <RouteAuto
        {...args}
        onSave={(data) => {
          args.onSave(data);
          clos();
        }}
      />
    ),
  });
};
